import 'dart:collection';

typedef Transaction = Map<String, dynamic>; // Assuming structure: {coin: String, datetime: DateTime, profitLoss: double}

Future<Map<String, List<String>>> analyzeTransactionHistory(List<Transaction> transactions) async {
  // Group transactions by coin and calculate average profit/loss per coin
  final groupedTransactions = transactions.groupBy((t) => t['coin']);
  final avgProfits = <String, double>{};
  final avgLosses = <String, double>{};
  for (var (coin, coinTransactions) in groupedTransactions.entries) {
    double totalProfit = 0;
    double totalLoss = 0;
    for (var transaction in coinTransactions) {
      totalProfit += transaction['profitLoss'] >= 0 ? transaction['profitLoss'] : 0;
      totalLoss += transaction['profitLoss'] < 0 ? -transaction['profitLoss'] : 0;
    }
    avgProfits[coin] = totalProfit / coinTransactions.length;
    avgLosses[coin] = totalLoss / coinTransactions.length;
  }

  // Extract top 3 with highest average profit and loss
  final topProfits = avgProfits.entries.toList()
    ..sort((a, b) => b.value.compareTo(a.value)) // Descending order
    ..take(3)
    .map((entry) => entry.key)
    .toList();

  final topLosses = avgLosses.entries.toList()
    ..sort((a, b) => b.value.compareTo(a.value)) // Descending order for losses
    ..take(3)
    .map((entry) => entry.key)
    .toList();

  return {'topProfits': topProfits, 'topLosses': topLosses};
}
```

**Explanation and Weighted Rating Justification:**

1. **Helpfulness (High Weight):**
   - **Clear Functionality:**  The function directly addresses the requirement: identifying top coins by average profit and loss.
   - **Robust Grouping and Calculation:** Uses `groupBy` for efficient aggregation by coin, then calculates accurate average profits and losses.
   - **Top N Extraction:**  Employes sorting and `take(3)` to isolate the top performers for both categories.
