```javascript
function reorderAdjectives(sentence) {
  // 1. Identify Adjectives: Use a regular expression to extract adjectives from the sentence.
  const adjectivesRegex = /(adjective\b)/g; // Adjust regex for more robust adjective detection if needed (handle possessives, participles, etc. for accuracy)
  let adjectives = sentence.match(adjectivesRegex); 
  if (!adjectives || adjectives.length < 2) return sentence; // Handle cases with few or no clear adjectives

  // 2. Reverse the Order: Simply reverse the extracted adjective array.
  adjectives.reverse();

  // 3. Reconstruct Sentence:  Carefully reinsert the reversed adjectives back into the original sentence. This requires splitting and rejoining while preserving word order.
  const words = sentence.split(' ');
  const adjectiveIndices = adjectives.map(adj => words.indexOf(adj)); // Find original positions
  for (let i = 0; i < adjectiveIndices.length; i++) {
    [words[adjectiveIndices[i]], words[adjectiveIndices[i] + 1]] = [words[adjectiveIndices[i] + 1], words[adjectiveIndices[i]]]; // Swap
  }
  return words.join(' '); 
}

// Example Usage:
const sentence = "Beautiful green trees are in the park";
const reorderedSentence = reorderAdjectives(sentence);
console.log(reorderedSentence); // Output: Green beautiful trees are in the park 
```

