```cpp
#include <iostream>
#include <limits>

using namespace std;

// Recursive Fibonacci function
int fibonacci(int a, int b, int n) {
    if (n == 1) return a;
    if (n == 2) return b;
    return fibonacci(b, a + b, n - 1);
}

// Function to generate and print the Fibonacci sequence
void generateFibonacci(int start1, int start2, int count) {
    if (count <= 0) {
        cerr << "Error: Invalid sequence length (must be positive)." << endl;
        return;
    }

    // Input validation - ensure both starts are non-negative
    if (start1 < 0 || start2 < 0) {
        cerr << "Error: Starting values must be non-negative integers." << endl;
        return;
    }

    cout << start1 << ", " << start2 << ", ";  // Print initial values

    for (int i = 3; i <= count; ++i) {
        int nextFib = fibonacci(start1, start2, i);
        cout << nextFib << " ";
        // Update for next iteration
        start1 = start2;
        start2 = nextFib;
    }
    cout << endl;
}

int main() {
    int start1, start2, length;

    cout << "Enter the first two Fibonacci numbers: ";
    while (!(cin >> start1 >> start2)) {  // Input validation loop
        cin.clear();
        cin.ignore(numeric_limits<streamsize>::max(), '\n');
        cerr << "Error: Invalid input. Please enter integers only." << endl;
    }

    cout << "Enter the desired sequence length: ";
    while (!(cin >> length)) {  // Input validation loop
        cin.clear();
        cin.ignore(numeric_limits<streamsize>::max(), '\n');
        cerr << "Error: Invalid input. Please enter a positive integer." << endl;
    }

    generateFibonacci(start1, start2, length);

    return 0;
}
