var subtitleText = loadFile(subtitleFile).toString().split('\n'); // Read subtitles line by line
var textLayer = compMain.layers.addText(subtitleText[0]); // Initial text layer
textLayer.transform.position = [0, layer1.contentHeight - 30]; // Bottom of top layer
textLayer.fontSize = 24; // Adjust font size as needed
textLayer.color = [1, 1, 1, 1]; // White color

// 4. Animate Subtitles (Keyframe Approach)
var currentFrame = 0;
subtitleText.forEach(line => {
  textLayer.textContent = line;
  textLayer.effect("Position")("anchorPoint").setValueAtTime(currentFrame, [0.5, 1]); // Center anchor
  currentFrame += textLayer.duration; //  Advance frame for next subtitle
  compMain.duplicateLayer(textLayer); // Create a new text layer for each subtitle
  compMain.activeLayer.startTime = currentFrame; // Start new subtitle at correct time
});

